INSERT OR REPLACE INTO `post` (`id`, `user_id`, `title`, `content`, `media_url`, `media_type`, `media_urls`, `aspect_ratio`, `location`, `camera_meta`, `tags`, `post_type`, `likes_count`, `comments_count`, `shares_count`)
VALUES
  ('post-1', 'usr_elena_dev', 'Quiet Brutalism: Concrete Light & Shadows', 'A study on natural dawn illumination casting geometric shadows across raw exposed concrete in the central atrium. Shot on 35mm f/1.4. The spatial tension transforms throughout the winter solstice.', 'https://images.unsplash.com/photo-1513694203232-719a280e022f?w=1200&auto=format&fit=crop&q=80', 'image', '[{"url":"https://images.unsplash.com/photo-1513694203232-719a280e022f?w=1200&auto=format&fit=crop&q=80","type":"image"},{"url":"https://images.unsplash.com/photo-1600585154340-be6161a56a0c?w=1200&auto=format&fit=crop&q=80","type":"image"},{"url":"https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?w=1200&auto=format&fit=crop&q=80","type":"image"},{"url":"https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?w=1200&auto=format&fit=crop&q=80","type":"image"}]', '4:5', 'Fondazione Prada, Milano', '35mm · ISO 200', '["#MinimalArchitecture", "#LightAndSpace", "#DesignArchive"]', 'photo', 842, 46, 12),
  ('post-2', 'usr_kai_dev', 'Wabi-Sabi Clay & Stoneware Forms', 'Hand-pinched Shigaraki stoneware fired in an anagama kiln over seven days. The ash melt creates an unrepeatable landscape of mineral hues and subtle texture.', 'https://images.unsplash.com/photo-1578749556568-bc2c40e68b61?w=1200&auto=format&fit=crop&q=80', 'image', '[{"url":"https://images.unsplash.com/photo-1578749556568-bc2c40e68b61?w=1200&auto=format&fit=crop&q=80","type":"image"}]', '1:1', 'Kyoto, Japan', '50mm · ISO 400', '["#KyotoCeramics", "#WabiSabi", "#JapaneseCraft"]', 'photo', 618, 29, 8),
  ('post-3', 'usr_sophia_dev', 'Nordic Monolith: Timber & Slate Textures', 'Tactile cedar and natural slate slabs balancing acoustic warmth with Nordic brutalist geometry.', 'https://images.unsplash.com/photo-1541123437800-1bb1317badc2?w=1200&auto=format&fit=crop&q=80', 'image', '[{"url":"https://images.unsplash.com/photo-1541123437800-1bb1317badc2?w=1200&auto=format&fit=crop&q=80","type":"image"}]', '4:5', 'Stockholm, Sweden', '28mm · ISO 100', '["#NordicDesign", "#TimberArchitecture", "#TactileSpaces"]', 'photo', 512, 18, 5),
  ('post-4', 'usr_lars_dev', 'Mineral Azimuth: Fjord Mist & Raw Stone', 'Dolomite rock formations reflected through dawn moisture along the Sognefjord mountain pass.', 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?w=1200&auto=format&fit=crop&q=80', 'image', '[{"url":"https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?w=1200&auto=format&fit=crop&q=80","type":"image"}]', '1:1', 'Vestland, Norway', '80mm · ISO 200', '["#AlpineMinimalism", "#FjordLandscape", "#RawEarth"]', 'photo', 437, 22, 9),
  ('post-5', 'usr_elena_dev', 'Spiral Concrete: Geometry in Rotation', 'Continuous spiral staircase forming a helical prism through the skylight atrium.', 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?w=1200&auto=format&fit=crop&q=80', 'image', '[{"url":"https://images.unsplash.com/photo-1600585154340-be6161a56a0c?w=1200&auto=format&fit=crop&q=80","type":"image"}]', '4:5', 'Helsinki, Finland', '35mm · ISO 400', '["#HelicalForm", "#BrutalistStairs", "#DesignArchive"]', 'photo', 720, 35, 14),
  ('post-6', 'usr_kai_dev', 'Charred Yakisugi Cedar: Fire & Longevity', 'Surface preservation through controlled combustion. The blackened timber absorbs dawn light with velvety depth.', 'https://images.unsplash.com/photo-1579783902614-a3fb3927b675?w=1200&auto=format&fit=crop&q=80', 'image', '[{"url":"https://images.unsplash.com/photo-1579783902614-a3fb3927b675?w=1200&auto=format&fit=crop&q=80","type":"image"}]', '1:1', 'Nara, Japan', '50mm · ISO 160', '["#Yakisugi", "#KyotoCraft", "#JapaneseWoodwork"]', 'photo', 589, 27, 11);

